import ctypes
from numpy import array, zeros

def gsl_matrix_alloc(rows, cols):
    return gsl.gsl_matrix_alloc(rows, cols)

def gsl_matrix_free(matrix):
    gsl.gsl_matrix_free(matrix)

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_mat = gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_mat[i][j] = np_array[i, j]
    return gsl_mat

def gsl_matrix_to_numpy(gsl_matrix):
    rows = int(gsl_matrix.size1)
    cols = int(gsl_matrix.size2)
    np_array = zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            np_array[i, j] = gsl_matrix[i][j]
    return np_array

def compute_covariance(jacobian, epsrel, out_rows, out_cols):
    assert isinstance(jacobian, array), "Jacobian must be a numpy array"
    assert isinstance(epsrel, float), "epsrel must be a float"
    assert isinstance(out_rows, int) and isinstance(out_cols, int), "Output dimensions must be integers"

    jacobian_gsl = numpy_to_gsl_matrix(jacobian)
    covar_gsl = gsl_matrix_alloc(out_rows, out_cols)

    try:
        gsl.gsl_multifit_covar(jacobian_gsl, epsrel, covar_gsl)
        covar_np = gsl_matrix_to_numpy(covar_gsl)
    finally:
        gsl_matrix_free(jacobian_gsl)
        gsl_matrix_free(covar_gsl)

    return covar_np

