import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)

    def set_data(self, data):
        for i in range(data.shape[0]):
            for j in range(data.shape[1]):
                gsl.gsl_matrix_set(self.matrix, i, j, data[i, j])

    def get_data(self):
        return gsl_matrix_to_numpy(self.matrix)

def numpy_to_gsl_matrix(np_array):
    gsl_matrix = GSLMatrix(np_array.shape[0], np_array.shape[1])
    gsl_matrix.set_data(np_array)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.matrix.size1
    cols = gsl_matrix.matrix.size2
    data = np.zeros((rows, cols), dtype=np.float64)
    for i in range(rows):
        for j in range(cols):
            data[i, j] = gsl.gsl_matrix_get(gsl_matrix.matrix, i, j)
    return data

def compute_covariance(jacobian, epsrel):
    rows, cols = jacobian.shape
    covariance = GSLMatrix(rows, cols)
    gsl_multifit_covar(numpy_to_gsl_matrix(jacobian), epsrel, covariance.matrix)
    return covariance.get_data()

