gsl.gsl_integration_qk51.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
gsl.gsl_integration_qk51.restype = ctypes.c_int

class GSLFunction:
    def __init__(self, func: Callable[[float], float]):
        self.func = func
        self.callback = self.test_func

    @staticmethod
def test_func(x: ctypes.c_double) -> ctypes.c_double:
        return ctypes.c_double(self.func(x.value))

def integrate_qk51(func: Callable[[float], float], a: float, b: float) -> tuple[float, float]:
    gsl_func = GSLFunction(func)
    result = ctypes.c_double(0.0)
    abserr = ctypes.c_double(0.0)
    status = gsl.gsl_integration_qk51(gsl_func.test_func, a, b, None, 1, ctypes.byref(result), ctypes.byref(abserr))
    if status != 0:
        raise ValueError(f"Integration failed with status {status}")
    return result.value, abserr.value

