class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.callback = self._callback_func()

    def _callback_func(self):
        return ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self.callback_func)

    def callback_func(self, x):
        result = ctypes.c_double()
        self.func(x, ctypes.byref(result))
        return result.value

class GSLIntegrationWorkspace:
    def __init__(self, epsabs, epsrel, limit, key):
        self.epsabs = epsabs
        self.epsrel = epsrel
        self.limit = limit
        self.key = key
        self.workspace_ptr = gsl.gsl_integration_workspace_alloc(self.limit)

    def integrate(self, func, a, b):
        result = ctypes.c_double()
        abserr = ctypes.c_double()
        gsl.gsl_integration_qag(
            func.callback,
            a,
            b,
            self.epsabs,
            self.epsrel,
            self.limit,
            self.key,
            self.workspace_ptr,
            ctypes.byref(result),
            ctypes.byref(abserr)
        )
        return result.value, abserr.value

    def __del__(self):
        gsl.gsl_integration_workspace_free(self.workspace_ptr)

def integrate_function(function, a, b, epsabs, epsrel, limit, key):
    gsl_func = GSLFunction(function)
    workspace = GSLIntegrationWorkspace(epsabs, epsrel, limit, key)
    result, error = workspace.integrate(gsl_func, a, b)
    return result, error

