    generator_type = b"halton"
    qrng = gsl.gsl_qrng_alloc(generator_type)
    if not qrng:
        return json.dumps({"error": "Failed to allocate QRNG."})

    status = gsl.gsl_qrng_init(qrng)
    if status != 0:
        gsl.gsl_qrng_free(qrng)
        return json.dumps({"error": "QRNG initialization failed."})

