        self.data = (ctypes.c_double * (self.rows * self.cols))()\n        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = data[i][j]

    def __del__(self):
        pass

# Function to convert matrix to GSLMatrix
def matrix_to_gsl(matrix: List[List[float]]) -> GSLMatrix:
    return GSLMatrix(matrix)

# Function to convert GSLMatrix to numpy array
def gsl_matrix_to_numpy(gsl_matrix: GSLMatrix) -> np.ndarray:
    import numpy as np
    return np.ctypeslib.as_array(gsl_matrix.data, (gsl_matrix.rows, gsl_matrix.cols))

# Function to compute matrix exponential
def compute_matrix_exponential(matrix: List[List[float]], mode: int) -> List[List[float]]:
    if not all(len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("Input must be a square matrix")
    gsl_matrix = matrix_to_gsl(matrix)
    result = (ctypes.c_double * (gsl_matrix.rows * gsl_matrix.cols))()
    gsl.gsl_linalg_exponential_ss(ctypes.byref(gsl_matrix.data), gsl_matrix.rows, ctypes.byref(result), mode)
    return gsl_matrix_to_numpy(GSLMatrix([[result[i * gsl_matrix.cols + j] for j in range(gsl_matrix.cols)] for i in range(gsl_matrix.rows)])).tolist()

