# Define the GSLMatrix class
class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.matrix_ptr = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(self.matrix_ptr, i, j, data[i][j])

    def retrieve_gsl_matrix(self):
        result = [[0.0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = gsl.gsl_matrix_get(self.matrix_ptr, i, j)
        return result

    def free_gsl_matrix(self):
        gsl.gsl_matrix_free(self.matrix_ptr)

def create_gsl_matrix(data):
    return GSLMatrix(data)

def retrieve_gsl_matrix(gsl_matrix):
    return gsl_matrix.retrieve_gsl_matrix()

def free_gsl_matrix(gsl_matrix):
    gsl_matrix.free_gsl_matrix()

