# Load dynamic libraries in the correct order
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))()\n        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = data[i][j]
        self.gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        ctypes.memmove(gsl.gsl_matrix.data, self.data, ctypes.sizeof(ctypes.c_double) * (self.rows * self.cols))

    def __del__(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

    @staticmethod
def create_gsl_matrix(data):
        return GSLMatrix(data)

    @staticmethod
def retrieve_gsl_matrix(gsl_matrix):
        rows = int(gsl_matrix.size1)
        cols = int(gsl_matrix.size2)
        data = [([0] * cols) for _ in range(rows)]
        ctypes.memmove(ctypes.c_void_p(data[0][0]), gsl_matrix.data, ctypes.sizeof(ctypes.c_double) * (rows * cols))
        return data

    @staticmethod
def free_gsl_matrix(gsl_matrix):
        gsl.gsl_matrix_free(gsl_matrix)

