def conj_memcpy(dest, src):
    if len(dest) != len(src):
        return -1  # Error: vectors must have the same size
    dest_ptr = (GSLVector)(*dest)
    src_ptr = (GSLVector)(*src)
    status = vector_conj_memcpy(ctypes.byref(dest_ptr), ctypes.byref(src_ptr))
    if status != 0:
        return -1  # Error: failed to copy
    return 0  # Success
