import ctypes

def load_gsl_libs():
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    return ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def cblas_dsymm(A, B, alpha, beta, Order='C', Side='L', Uplo='U', M=None, N=None, lda=None, ldb=None, ldc=None):
    gsl = load_gsl_libs()
    if M is None:
        M = A.shape[0]
    if N is None:
        N = B.shape[1]
    if lda is None:
        lda = M
    if ldb is None:
        ldb = M
    if ldc is None:
        ldc = M
    A_ptr = A.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    B_ptr = B.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    C_ptr = (ctypes.c_double * (M * N)).in_dll(gsl, "C")
    gsl.cblas_dsymm(Order.encode(), Side.encode(), Uplo.encode(), M, N, alpha, A_ptr, lda, B_ptr, ldb, beta, C_ptr, ldc)
    return np.frombuffer(C_ptr, dtype=np.double).reshape(M, N)

