class GSLMatrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = data[i][j]

    def is_positive_definite(self):
        result = gsl.gsl_linalg_cholesky_decomp(ctypes.byref(self.data), ctypes.c_int(self.rows))
        return result == 0

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError("Matrix is not positive definite")
        l_matrix = [[0.0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(i + 1):
                sum_val = 0.0
                if i == j:
                    sum_val = self.data[i * self.cols + j]
                    for k in range(j):
                        sum_val -= l_matrix[j][k] ** 2
                    l_matrix[j][j] = ctypes.c_double(sum_val).value ** 0.5
                else:
                    sum_val = self.data[i * self.cols + j]
                    for k in range(j):
                        sum_val -= l_matrix[i][k] * l_matrix[j][k]\                    l_matrix[i][j] = ctypes.c_double(sum_val).value / l_matrix[j][j]
        return l_matrix

