import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

GSL_SUCCESS = 0

GSL_REAL = ctypes.c_double
class gsl_function(ctypes.Structure):
    _fields_ = [(\"function\", ctypes.CFUNCTYPE(GSL_REAL, GSL_REAL, ctypes.POINTER(ctypes.c_void_p))), (\"params\", ctypes.c_void_p)]

def func_wrapper(x, params):
    py_func = ctypes.cast(params, ctypes.py_object).value
    return py_func(x)

compute_integral = gsl.gsl_integration_romberg
compute_integral.argtypes = [ctypes.POINTER(gsl_function), GSL_REAL, GSL_REAL, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
compute_integral.restype = ctypes.c_int

def integrate(py_func, a, b, epsabs, epsrel, n):
    func = gsl_function()
    func.function = ctypes.CFUNCTYPE(GSL_REAL, GSL_REAL, ctypes.POINTER(ctypes.c_void_p))(func_wrapper)
    func.params = ctypes.py_object(py_func)

    result = ctypes.c_double()
    abserr = ctypes.c_double()
    workspace = gsl.gsl_integration_romberg_alloc(n)

    status = compute_integral(func, a, b, n, ctypes.byref(result), ctypes.byref(abserr))

    gsl.gsl_integration_romberg_free(workspace)

    if status != GSL_SUCCESS:
        raise Exception(f"Integration failed with status: {status}")

    return result.value, abserr.value

